//! City Gen v4, phase 1: the airport claims its land before the graded roads, and the
//! validator holds it (claims.rs, validate.rs). The live Commons is generated by the
//! shared `commons3` (v3_tests.rs).

use super::claims::Airport;
use super::profile::district;
use super::v3_tests::{commons3, island3};
use super::*;

fn commons_claim() -> Airport {
    Airport::of(&commons3().layers.sites).expect("the Commons has an airport")
}

#[test]
fn the_commons_breaks_no_hard_rule() {
    let v = validate::hard(&commons3().layers);
    assert!(v.is_empty(), "{}", validate::report(&v));
}

#[test]
fn no_highway_or_ring_runs_through_the_commons_airport() {
    let a = commons_claim();
    let mut behind = false;
    for e in commons3().layers.roads.edges.iter().filter(|e| roads::is_graded(e.class)) {
        for s in e.points.windows(2) {
            let (p, q) = ((s[0][0], s[0][2]), (s[1][0], s[1][2]));
            assert!(!a.meets_seg(p, q, e.width / 2), "{} {} enters the airport", e.class, e.name);
            // only the ring runs in the corridor behind the terminal
            assert!(e.class == "ring" || !a.in_corridor(p, q, e.width / 2), "{} {} behind the terminal", e.class, e.name);
            behind |= e.class == "ring" && a.in_corridor(p, q, 0);
        }
    }
    assert!(behind, "the ring passes behind the terminal, under the skybridge");
    // and it is still a ring: all six sections
    let names: std::collections::BTreeSet<&str> = commons3().layers.roads.edges.iter().filter(|e| e.class == "ring").map(|e| e.name.as_str()).collect();
    assert_eq!(names.len(), 6, "{names:?}");
}

#[test]
fn every_lot_and_the_commons_airport_stay_where_they_were() {
    // the pins of v3_tests hold the airport; here: the forecourt, car park and tower keep
    // roads off them too, and the HQ pool is untouched (v3_tests counts the 64 HQ lots)
    let a = commons_claim();
    assert_eq!(a.landside, 4);
    for e in &commons3().layers.roads.edges {
        for s in e.points.windows(2) {
            assert!(!a.polys[..a.landside].iter().any(|p| Airport::polys_meet(p, &[(s[0][0], s[0][2]), (s[1][0], s[1][2])], e.width / 2)), "{} {} crosses the landside", e.class, e.name);
        }
    }
}

#[test]
fn the_airports_grounds_grow_no_trees() {
    let d = &commons3().layers.districts;
    let a = commons_claim();
    let (forest, park) = (district::NAMES2.iter().position(|&n| n == "forest").unwrap() as u8, district::NAMES2.iter().position(|&n| n == "park").unwrap() as u8);
    let mut cells = 0;
    for iz in 0..d.n {
        for ix in 0..d.n {
            let q = (d.origin_cm + ix as i64 * d.cell_cm + d.cell_cm / 2, d.origin_cm + iz as i64 * d.cell_cm + d.cell_cm / 2);
            if a.contains(q) {
                cells += 1;
                let k = d.kinds[iz * d.n + ix];
                assert!(k != forest && k != park, "a tree district in the airport at {q:?}");
            }
        }
    }
    assert!(cells > 1_000, "{cells} cells under the claim");
}

#[test]
fn a_personal_island_has_no_airport_and_nothing_to_break() {
    assert!(Airport::of(&island3().layers.sites).is_none());
    assert!(validate::hard(&island3().layers).is_empty());
}

#[test]
fn other_commons_seeds_keep_off_their_airport_too() {
    // a few seeds with the Commons' profile, airports facing different ways
    for id in ["v4seed9@3", "v4seed21@3", "v4seed41@3"] {
        let w = generate(id, &[]).unwrap();
        assert!(Airport::of(&w.layers.sites).is_some(), "{id}: no airport");
        let v = validate::hard(&w.layers);
        assert!(v.is_empty(), "{id}:\n{}", validate::report(&v));
    }
}

/// Every one of 50 Commons-profile seeds that generates passes the validator (one,
/// v4seed7, has too few HQ lots, as before v4). Slow in a debug build: run it with
/// `cargo test --release -- --ignored fifty`.
#[test]
#[ignore]
fn fifty_seeds_break_no_hard_rule() {
    for i in 1..=50 {
        let id = format!("v4seed{i}@3");
        let Ok(w) = generate(&id, &[]) else { continue };
        let v = validate::hard(&w.layers);
        assert!(v.is_empty(), "{id}:\n{}", validate::report(&v));
    }
}

/// Phase 3: a junction's control comes from the roads that meet there.
mod junctions {
    use super::super::roads::{Edge, Node, Roads, MINI_ISLAND_CM, ROUNDABOUT_ISLAND_CM};
    use super::super::transit::Transit;

    fn node(id: u32, x: i64, z: i64) -> Node {
        Node { id, x, y: 0, z, junction: None, island: None }
    }

    fn road(id: u32, a: u32, b: u32, class: &'static str, name: &str, pts: [(i64, i64); 2]) -> Edge {
        Edge {
            id, a, b, class: if matches!(class, "avenue" | "boulevard") { "arterial" } else { "local" }, width: 1_200, walk: 250, lanes: 1, route: None, name: name.to_string(),
            points: pts.iter().map(|p| [p.0, 0, p.1]).collect(), min_tier: None, bridge: None, v4: None, median: None,
        }
        .classed(Some(class))
    }

    /// A junction at the origin with three arms of `classes`, each `len` cm long; arms with the
    /// same `names` are one road running on through it.
    fn star(classes: [&'static str; 3], len: i64, names: [&str; 3]) -> Roads {
        let ends = [(len, 0), (-len / 2, len), (-len / 2, -len)];
        let mut nodes = vec![node(0, 0, 0)];
        let mut edges = Vec::new();
        for (k, (c, e)) in classes.iter().zip(ends).enumerate() {
            nodes.push(node(k as u32 + 1, e.0, e.1));
            edges.push(road(k as u32, 0, k as u32 + 1, c, names[k], [(0, 0), e]));
        }
        Roads { nodes, edges }
    }

    #[test]
    fn collectors_meet_at_a_roundabout_where_it_fits_else_a_mini_one() {
        let none = Transit { lines: Vec::new() };
        // three roads: two collectors and a local street
        const THREE: [&str; 3] = ["A Road", "B Road", "C Street"];
        let mut r = star(["collector", "collector", "local"], 6_000, THREE);
        r.junctions(&none, &[]);
        assert_eq!((r.nodes[0].junction, r.nodes[0].island), (Some("roundabout"), Some(ROUNDABOUT_ISLAND_CM)));
        // a lot 10 m from the middle: no room for the 32 m circle
        let lot = vec![(1_000, 500), (1_500, 500), (1_500, 1_000), (1_000, 1_000)];
        let mut r = star(["collector", "collector", "local"], 6_000, THREE);
        r.junctions(&none, &[lot]);
        assert_eq!((r.nodes[0].junction, r.nodes[0].island), (Some("mini"), Some(MINI_ISLAND_CM)));
        // short arms: a mini one too
        let mut r = star(["collector", "collector", "local"], 3_000, THREE);
        r.junctions(&none, &[]);
        assert_eq!(r.nodes[0].junction, Some("mini"));
    }

    #[test]
    fn side_streets_give_way_and_avenues_get_lights() {
        let none = Transit { lines: Vec::new() };
        // a T: the first two arms one road running on through, the third a side road
        let t = ["Main Road", "Main Road", "Side Street"];
        for (classes, names, want) in [
            (["local", "local", "lane"], t, "priority"),
            (["avenue", "avenue", "local"], t, "priority"),
            (["collector", "collector", "local"], t, "priority"),
            (["avenue", "avenue", "avenue"], t, "signals"),
            (["avenue", "avenue", "collector"], t, "roundabout"),
        ] {
            let mut r = star(classes, 6_000, names);
            r.junctions(&none, &[]);
            assert_eq!(r.nodes[0].junction, Some(want), "{classes:?}");
        }
    }

    #[test]
    fn a_main_road_crossing_a_side_street_has_lights_spaced_out() {
        let none = Transit { lines: Vec::new() };
        // a four-way: Main Road on through, Side Street across it
        let ends = [(6_000, 0), (-6_000, 0), (0, 6_000), (0, -6_000)];
        let (cls, names) = (["avenue", "avenue", "local", "local"], ["Main Road", "Main Road", "Side Street", "Side Street"]);
        let mut nodes = vec![node(0, 0, 0)];
        let mut edges = Vec::new();
        for k in 0..4 {
            nodes.push(node(k as u32 + 1, ends[k].0, ends[k].1));
            edges.push(road(k as u32, 0, k as u32 + 1, cls[k], names[k], [(0, 0), ends[k]]));
        }
        let mut r = Roads { nodes, edges };
        r.junctions(&none, &[]);
        assert_eq!(r.nodes[0].junction, Some("signals"));
    }

    #[test]
    fn a_tram_across_a_junction_never_meets_a_roundabout() {
        use super::super::transit::Line;
        let tram = Transit { lines: vec![Line { id: "T1".into(), kind: "tram", tier: 4, stops: Vec::new(), path: vec![1, 0, 2] }] };
        let three = ["A Road", "B Road", "C Street"];
        let mut r = star(["collector", "collector", "local"], 6_000, three);
        r.junctions(&tram, &[]);
        assert_eq!(r.nodes[0].junction, Some("priority"));
        let mut r = star(["avenue", "collector", "local"], 6_000, three);
        r.junctions(&tram, &[]);
        assert_eq!(r.nodes[0].junction, Some("signals"));
    }
}
